INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12093-swe216', 'stk-user12093', 'SWE 216', 'doc', '{"docs": [{"id": "stk-dr-f99239", "n": "Dr. Jameleddine Hassine", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "SWE 216 - Term 212\n\nالتحضير: عبر تمرير ورقة بداية المحاضرة ويستلمها نهاية المحاضرة أو عند أخذ جميع الطلاب للتحضير.\n\nطريقة الشرح: يشرح سلايدات المادة سيئة الذكر، مع الكتابة على السبورة لتوضيح المفاهيم، شرحه ممتاز ومفهوم.\n\nالكويزات: اختبرنا 4 كويزات، سهلة إلى متوسطة المستوى، العيب الوحيد الذي لاحظته في كويزاته التركيزُ على بعض الأجزاء من موضوع الكويز وإهمال البقية حتى ولو كانت ذا أهمية، يعني لا تستغرب شابتر عبارة عن 70 صفحة/سلايدة ويكون الكويز على فقط 10% من المحتوى!\n\nالمياجر: اختبار نصفي(Midterm Exam) مشترك.\n\nالفانيلات: مشترك.\n\nالقريد النهائي: A.\n\nالصوت: واضح بلكنة المغرب العربي.\n\nإضافات: الدكتور فاهم ومتمكن في موضوع المادة، وهو software requirements engineering، لكونه أحد مجالات بحثه؛ لذلك لو كانت المادة عن هذا الموضوع فأنصح به. الدكتور أيضا مرِن جدا في المواعيد، لا أحصي كم مرة أجّل فيها كويز أو موعد تسليم بروجكت.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534521-swe216", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jameleddine-hassine/99239/7", "user": "user12093", "ts": 1653980069000, "tid": 99239, "pn": 7}}]}', 1653980069000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
